import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'mock-probe',
  description:
    'Probe the live fake feed service for this eval: fetches the current items for every topic in topics.json and returns the raw JSON bodies as evidence for the brief.',
  inputs: {},
  outputs: {
    feeds: { type: 'string', description: 'JSON object mapping each topic id to the raw feed response body.' },
  },
  requires: ['workspace.read', 'network', 'credential:mock.feeds'],
});

const services = JSON.parse(await gezel.fs.read('mocks/services.json'));
const base = (id) => {
  const service = services.find((entry) => entry.id === id);
  if (!service) throw new Error(`mock service "${id}" is not listed in mocks/services.json`);
  return service.baseUrl;
};

const topics = JSON.parse(await gezel.fs.read('topics.json'));
const out = {};
for (const topic of topics) {
  const res = await gezel.http.authed(`${base('feeds')}/feeds/${topic.id}`, {
    credential: 'mock.feeds',
  });
  if (!res.ok) throw new Error(`feed fetch failed for ${topic.id}: ${res.status} ${res.body}`);
  out[topic.id] = res.body;
}

gezel.output({ feeds: JSON.stringify(out) });
